import { MeshBasicNodeMaterial } from 'three/webgpu';
import { texture, uv, mix, vec3 } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, Color, SRGBColorSpace, ClampToEdgeWrapping } = ctx.THREE;

  const colors = config.intent?.visualSpec?.colors ?? {};
  const ink = new Color(colors.ink ?? '#16161d');
  const paper = new Color(colors.paper ?? '#e8ecf2');
  const accent = new Color(colors.accent ?? '#ff2a38');
  const surface = new Color(colors.surface ?? '#0b0b10');

  const root = new Group();
  const content = new Group();
  root.add(content);

  const disposables = [];

  // Atlas region 512x320 -> aspect 1.6 ; build a billboarded backdrop plane
  const planeW = 2.6;
  const planeH = planeW * (320 / 512); // 1.625
  const planeGeo = new PlaneGeometry(planeW, planeH);
  disposables.push(planeGeo);

  const planeMat = new MeshBasicNodeMaterial();
  planeMat.transparent = true;
  planeMat.colorNode = vec3(surface.r, surface.g, surface.b);
  disposables.push(planeMat);

  const backdrop = new Mesh(planeGeo, planeMat);
  backdrop.position.set(0, 0, -0.02);
  content.add(backdrop);

  // Load ceramic-grain texture and refine the surface with engineered grain
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      tex.colorSpace = SRGBColorSpace;
      tex.wrapS = ClampToEdgeWrapping;
      tex.wrapT = ClampToEdgeWrapping;
      tex.offset.set(0, 0);
      tex.repeat.set(1, 1);
      tex.needsUpdate = true;

      const g = texture(tex, uv());
      // Subtle grain: modulate between near-black surface and slightly lifted ink
      planeMat.colorNode = mix(
        vec3(surface.r, surface.g, surface.b),
        vec3(ink.r * 1.35, ink.g * 1.35, ink.b * 1.35),
        g.r.mul(0.22)
      );
      planeMat.needsUpdate = true;
    });
  }

  // Accent hairline (<=10% of frame) — signal red
  const accentGeo = new PlaneGeometry(0.52, 0.016);
  disposables.push(accentGeo);
  const accentMat = new MeshBasicNodeMaterial();
  accentMat.colorNode = vec3(accent.r, accent.g, accent.b);
  disposables.push(accentMat);
  const accentBar = new Mesh(accentGeo, accentMat);
  accentBar.position.set(0, -0.42, 0.01);
  content.add(accentBar);

  // Headline text via MSDF atlas (Lora display, paper white)
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  for (const item of items) {
    const textObj = ctx.fontAtlas.createText(String(item.text), {
      fontSize: 96,
      color: '#e8ecf2',
      align: 'center',
      letterSpacingPx: 0
    });
    // headline type scale ~0.34 scene units
    textObj.scale.setScalar(0.0036);
    textObj.position.set(0, 0.03, 0.02);
    content.add(textObj);
  }

  // Entrance: rise-in + weighted-settle (no linear easing on hero)
  content.position.y = 0.4;
  content.scale.setScalar(0.96);

  const tl = gsap.timeline();
  tl.to(content.position, { y: 0, duration: 0.7, ease: 'power3.out' });
  tl.to(content.scale, { x: 1.04, y: 1.04, z: 1.04, duration: 0.5, ease: 'power2.out' }, 0);
  tl.to(content.scale, { x: 1, y: 1, z: 1, duration: 0.9, ease: 'power4.out' }, 0.5);

  // Sprite billboards toward camera (camera at +z, plane default normal +z) -> rotation (0,0,0)
  root.rotation.set(0, 0, 0);

  root.userData.handlers = {};
  root.userData.cleanup = () => {
    tl.kill();
    for (const d of disposables) {
      if (d && typeof d.dispose === 'function') d.dispose();
    }
    content.traverse((o) => {
      if (o.geometry && typeof o.geometry.dispose === 'function') o.geometry.dispose();
      if (o.material) {
        if (Array.isArray(o.material)) o.material.forEach((m) => m.dispose && m.dispose());
        else if (typeof o.material.dispose === 'function') o.material.dispose();
      }
    });
  };

  return root;
}
